const DEMO_IMG = 'art/repdb/';
let _demo = { name:null, images:[], i:0, data:null };

/* lookup par nom d'exercice (g\u00e8re alias FR via exoKey) */
function illustrationFor(name){
  if (!name) return null;
  const k = (typeof exoKey === 'function' ? exoKey(name) : String(name).toLowerCase().trim());
  return ILLUSTRATIONS[k] || null;
}

function _stepLabel(file, i, total){
  if (total <= 1) return '';
  if (/start/i.test(file)) return 'Start';
  if (/peak/i.test(file)) return 'Peak';
  return 'Step ' + (i + 1);
}

/* Miniature disc\u00e8te (lazy) pour une liste ; '' si pas d'illustration. */
function libThumb(name){
  const d = illustrationFor(name);
  if (!d || !d.images || !d.images.length) return '';
  const q = "'" + "'";
  return '<span class="lib-thumb" role="button" tabindex="0" data-demo="1" ' +
    'aria-label="View demonstration" ' +
    'onclick="event.stopPropagation();openDemo(\'' + esc(name) + '\')" ' +
    'onkeydown="if(event.key===\'Enter\'||event.key===\' \'){event.preventDefault();event.stopPropagation();openDemo(\'' + esc(name) + '\')}">' +
    '<img src="' + DEMO_IMG + esc(d.images[0]) + '" alt="" loading="lazy" decoding="async" ' +
    'onerror="this.closest(\'.lib-thumb\')&&(this.closest(\'.lib-thumb\').style.display=\'none\')">' +
    '</span>';
}

/* Bouton d\u00e9mo (ic\u00f4ne) pour un en-t\u00eate d'exercice (s\u00e9ance active…). */
function demoBtn(name){
  const d = illustrationFor(name);
  if (!d || !d.images || !d.images.length) return '';
  return '<button class="ex-demo" type="button" title="View demonstration" ' +
    'aria-label="View demonstration" onclick="openDemo(\'' + esc(name) + '\')">' +
    icon('play') + '</button>';
}

function openDemo(name){
  const d = illustrationFor(name);
  if (!d || !d.images || !d.images.length){ toast('No illustration for this exercise yet.'); return; }
  _demo = { name, images:d.images, i:0, data:d };
  document.getElementById('demoTitle').textContent = name;
  _renderDemo();
  openModal('demoModal');
}

function _renderDemo(){
  const d = _demo.data, imgs = _demo.images, name = _demo.name;
  const file = imgs[_demo.i];
  const multi = imgs.length > 1;
  const label = _stepLabel(file, _demo.i, imgs.length);
  const alt = name + (label ? ' \u2014 ' + label : '');
  document.getElementById('demoStage').innerHTML =
    '<img src="' + DEMO_IMG + esc(file) + '" alt="' + esc(alt) + '" decoding="async" onerror="demoImgError(this)">' +
    (multi ? '<span class="demo-step-tag">' + esc(label || ('Step ' + (_demo.i + 1))) +
      ' \u00b7 ' + (_demo.i + 1) + '/' + imgs.length + '</span>' : '');
  const nav = document.getElementById('demoNav');
  nav.hidden = !multi;
  if (multi){
    document.getElementById('demoDots').innerHTML = imgs.map((_, i) =>
      '<span class="demo-dot' + (i === _demo.i ? ' on' : '') + '"></span>').join('');
    document.getElementById('demoPrev').disabled = _demo.i === 0;
    document.getElementById('demoNext').disabled = _demo.i === imgs.length - 1;
  }
  const muscles = (d.primary || []).concat(d.secondary || []).map(m => String(m).replace(/_/g, ' '));
  document.getElementById('demoMeta').innerHTML =
    (d.equipment ? '<span class="chip">Equip \u00b7 ' + esc(String(d.equipment).replace(/_/g, ' ')) + '</span>' : '') +
    (muscles.length ? '<span class="chip">Muscles \u00b7 ' + esc(muscles.slice(0, 4).join(', ')) + '</span>' : '');
  document.getElementById('demoInstr').innerHTML =
    (d.instructions && d.instructions.length)
      ? '<ol>' + d.instructions.map(s => '<li>' + esc(s) + '</li>').join('') + '</ol>'
      : (d.description ? '<p>' + esc(d.description) + '</p>' : '');
}

function demoStep(delta){
  const n = _demo.images.length;
  if (!n) return;
  _demo.i = Math.min(n - 1, Math.max(0, _demo.i + delta));
  _renderDemo();
}

function closeDemo(){ closeModal('demoModal'); }

/* Image de d\u00e9mo qui \u00e9choue : placeholder neutre, pas d'ic\u00f4ne cass\u00e9e. */
function demoImgError(img){
  img.style.display = 'none';
  const host = img.parentElement;
  if (host && !host.querySelector('.demo-fallback')){
    const fb = document.createElement('div');
    fb.className = 'demo-fallback';
    fb.textContent = 'Preview unavailable';
    host.appendChild(fb);
  }
}

Object.assign(window, { illustrationFor, libThumb, demoBtn, openDemo, demoStep, closeDemo, demoImgError });
